def test_create_update_delete_alias(self, kms): """Test CreateAlias, ListAliases, UpdateAlias, DeleteAlias.""" key1 = kms.create_key(Description="alias key 1") key1_id = key1["KeyMetadata"]["KeyId"] key2 = kms.create_key(Description="alias key 2") key2_id = key2["KeyMetadata"]["KeyId"] alias_name = "alias/compat-alias-crud" try: kms.create_alias(AliasName=alias_name, TargetKeyId=key1_id) aliases = kms.list_aliases() alias_names = [a["AliasName"] for a in aliases["Aliases"]] assert alias_name in alias_names
# Find target key alias_entry = next(a for a in aliases["Aliases"] if a["AliasName"] == alias_name) assert alias_entry["TargetKeyId"] == key1_id
# Update alias to point to key2 > kms.update_alias(AliasName=alias_name, TargetKeyId=key2_id)
